import{_ as n,C as s,o as i,c,aj as r,E as o,j as e,a}from"./framework.js";const I=JSON.parse('{"title":"AI 服务 | Cms / Settings | Documentation","description":"AI 服务用于配置站点级 AI 能力：向量搜索、MCP 服务、AI 函数、llms.txt、自动 Markdown 输出与全局 JSON-LD 映射。它在 站点设置 与 运维中心 各有一个菜单项，打开的是同一页面；本文只维护一份操作说明。","frontmatter":{"title":"AI 服务 | Cms / Settings | Documentation","description":"AI 服务用于配置站点级 AI 能力：向量搜索、MCP 服务、AI 函数、llms.txt、自动 Markdown 输出与全局 JSON-LD 映射。它在 站点设置 与 运维中心 各有一个菜单项，打开的是同一页面；本文只维护一份操作说明。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/ai-service.html"}]]},"headers":[],"relativePath":"zh/cms/settings/ai-service.md","filePath":"cms/settings/ai-service.md","lastUpdated":1780977342000}'),l={name:"zh/cms/settings/ai-service.md"};function h(g,t,m,b,p,_){const d=s("DocImage");return i(),c("div",null,[t[0]||(t[0]=r('<h1 id="ai-服务" tabindex="-1">AI 服务 <a class="header-anchor" href="#ai-服务" aria-label="Permalink to &quot;AI 服务&quot;">​</a></h1><blockquote><p>菜单：<strong>站点设置 → AI 服务</strong>（高级菜单） 同页入口：<strong>运维中心 → AI 服务</strong> 深链：<code>/_Admin/system/ai-service?SiteId={站点GUID}</code> Tab 深链：<code>name=settings</code> / <code>functions</code> / <code>vectorSearch</code> / <code>llms</code> / <code>markdown</code> / <code>jsonld</code></p></blockquote><p><strong>AI 服务</strong>用于配置站点级 AI 能力：向量搜索、MCP 服务、AI 函数、<code>llms.txt</code>、自动 Markdown 输出与全局 JSON-LD 映射。它在 <strong>站点设置</strong> 与 <strong>运维中心</strong> 各有一个菜单项，打开的是同一页面；本文只维护一份操作说明。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><table tabindex="0"><thead><tr><th>操作</th><th>权限</th></tr></thead><tbody><tr><td>打开 <strong>AI 服务</strong> 页面</td><td><code>ai</code></td></tr><tr><td>查看自定义 AI 函数列表</td><td><code>ai·view</code></td></tr><tr><td>新增、编辑、删除 AI 函数</td><td>界面按钮检查 <code>mcp·edit</code>；后端 <code>mcp/PostTool</code>、<code>mcp/DeleteTools</code> 检查 <code>ai·edit</code></td></tr><tr><td>运行自定义 AI 函数</td><td>界面按钮检查 <code>mcp·view</code></td></tr><tr><td>保存 <strong>MCP 服务</strong> 与 <strong>向量搜索</strong> 设置</td><td>页面底部保存按钮检查 <code>mcp·edit</code>，并保存站点 AI 设置</td></tr><tr><td>保存 <code>llms.txt</code>、Markdown、JSON-LD 配置</td><td>需能进入本页；其中 Markdown / JSON-LD 开关会保存站点 AI 设置</td></tr></tbody></table></div><div class="info custom-block"><p class="custom-block-title">支持范围</p><p>当前后台页面已开放并有服务端接口的 Tab 包括 <strong>MCP / AI 函数</strong>、<strong>llms.txt 生成器</strong>、<strong>自动 Markdown 引擎</strong>、<strong>全局 JSON-LD 映射</strong>。Pay-per-crawl 相关能力当前界面未开放，本篇不写。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>站点设置 → AI 服务</strong>，或勾选 <strong>运维中心 → AI 服务</strong>。</li><li>左侧打开对应菜单。两处入口都会进入 <code>/_Admin/system/ai-service</code>。</li></ol>',7)),o(d,{src:"/cms/settings/settings-ai-service-overview.png",alt:"AI 服务设置页",width:"1120"}),t[1]||(t[1]=e("h2",{id:"页面结构",tabindex:"-1"},[a("页面结构 "),e("a",{class:"header-anchor",href:"#页面结构","aria-label":'Permalink to "页面结构"'},"​")],-1)),t[2]||(t[2]=e("p",null,[a("页面按 Tab 组织，切换时 URL 写入 "),e("code",null,"name"),a(" 参数。")],-1)),o(d,{src:"/cms/settings/settings-ai-service-tabs.png",alt:"AI 服务 Tab",width:"1120"}),t[3]||(t[3]=r('<table tabindex="0"><thead><tr><th>Tab</th><th>用途</th><th>备注</th></tr></thead><tbody><tr><td><strong>设置</strong></td><td>开启向量搜索、选择 Embedding Provider / Model、开启 MCP 服务</td><td>默认 Tab</td></tr><tr><td><strong>AI 函数</strong></td><td>管理站点自定义函数，查看内置函数，并可试运行自定义函数</td><td>写入站点 <code>AIFunction</code> 仓库</td></tr><tr><td><strong>向量搜索</strong></td><td>查看各类对象索引状态，执行同步或重建</td><td>仅在 <strong>设置</strong> 中启用向量搜索后显示</td></tr><tr><td><strong>llms.txt 生成器</strong></td><td>生成、编辑并保存站点根路径 <code>/llms.txt</code></td><td>读取在线页面生成索引</td></tr><tr><td><strong>自动 Markdown 引擎</strong></td><td>开启 <code>.md</code> 路由输出，并维护覆盖规则</td><td>保存站点 <code>AI.MarkdownEngine</code></td></tr><tr><td><strong>全局 JSON-LD 映射</strong></td><td>将内容 / 数据库字段映射到 Schema.org 属性</td><td>保存站点 <code>AI.JsonLD</code> 与映射</td></tr></tbody></table><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>设置 Tab 先配底层能力，再去其它 Tab 同步或编写函数。</p>',3)),o(d,{src:"/cms/settings/settings-ai-service-settings.png",alt:"AI 服务设置 Tab",width:"1120"}),t[4]||(t[4]=r('<h3 id="向量搜索" tabindex="-1">向量搜索 <a class="header-anchor" href="#向量搜索" aria-label="Permalink to &quot;向量搜索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用向量搜索</strong></td><td>开启后站点保存 <code>ai.vectorSearch.enable</code>，页面会出现 <strong>向量搜索</strong> Tab</td></tr><tr><td><strong>Provider</strong></td><td>从支持 Embedding Models 的 AI Provider 中选择；若下拉为空，先确认组织级 AI Provider 是否可用</td></tr><tr><td><strong>Model</strong></td><td>选择该 Provider 下的 Embedding 模型；切换 Provider 时会自动带出第一个可用模型</td></tr></tbody></table><p>保存后，新建或更新的内容会按向量搜索逻辑进入索引；已有对象建议到 <a href="#向量搜索">向量搜索</a> Tab 执行一次同步或重建。</p><h3 id="mcp-服务" tabindex="-1">MCP 服务 <a class="header-anchor" href="#mcp-服务" aria-label="Permalink to &quot;MCP 服务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用 MCP 服务</strong></td><td>开启站点 MCP Server，使外部 MCP Client 可以连接并调用站点工具</td></tr><tr><td><strong>Development Connection Information</strong></td><td>非在线服务器会显示开发连接信息：<code>Endpoint</code> 与 <code>Authorization Header</code></td></tr><tr><td><strong>禁用内置 AI 工具</strong></td><td>关闭系统内置工具，只暴露用户创建的 AI 函数</td></tr></tbody></table><p><code>Endpoint</code> 由站点 <a href="./basic/general.html#站点信息">Base URL</a> 推导，并追加 <code>_mcp</code>；若 Base URL 仍是 <code>http</code>，页面显示时会转为 <code>https</code>。开发连接里的 Bearer Token 是当前登录用户凭据，只用于本机调试，不应写入文档、截图或代码仓库。</p><h2 id="ai-函数" tabindex="-1">AI 函数 <a class="header-anchor" href="#ai-函数" aria-label="Permalink to &quot;AI 函数&quot;">​</a></h2><p>AI 函数 Tab 分为 <strong>自定义</strong> 与 <strong>内置</strong>。自定义函数可被 MCP Server 暴露，也可被站点内 AI 调用；内置函数由系统提供，只在列表中查看名称与描述。</p>',8)),o(d,{src:"/cms/settings/settings-ai-service-functions.png",alt:"AI 函数自定义列表",width:"1120"}),t[5]||(t[5]=r('<p>若当前账号没有 <code>mcp·edit</code>，<strong>添加工具</strong> 按钮会显示为禁用态；请先在 <a href="./roles.html">角色权限</a> 中补齐权限。</p><h3 id="自定义列表" tabindex="-1">自定义列表 <a class="header-anchor" href="#自定义列表" aria-label="Permalink to &quot;自定义列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控件 / 列</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加工具</strong></td><td>打开 <a href="#ai-工具弹窗">AI 工具弹窗</a></td></tr><tr><td><strong>自定义 / 内置</strong></td><td>右上角切换当前列表</td></tr><tr><td><strong>名称</strong></td><td>自定义工具名称；新建保存后不建议再改</td></tr><tr><td><strong>标签</strong></td><td>从 <code>mcp/FunctionTags</code> 返回的标签中选择，用于分类和发现</td></tr><tr><td><strong>描述</strong></td><td>给 AI 或调用方理解用途的自然语言说明</td></tr><tr><td><strong>运行</strong></td><td>多选中仅选一条时显示，打开参数与结果弹窗</td></tr><tr><td><strong>编辑 / 删除</strong></td><td>编辑当前工具或多选删除</td></tr></tbody></table><h3 id="ai-工具弹窗" tabindex="-1">AI 工具弹窗 <a class="header-anchor" href="#ai-工具弹窗" aria-label="Permalink to &quot;AI 工具弹窗&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>新建必填、唯一，长度 1～50；编辑已有工具时禁用</td></tr><tr><td><strong>描述</strong></td><td>说明函数解决什么问题、何时调用、返回什么结果</td></tr><tr><td><strong>标签</strong></td><td>多选标签，便于内置发现逻辑筛选</td></tr><tr><td><strong>执行代码</strong></td><td>Monaco TypeScript 编辑器，启用 KScript 模式；这里只说明入口，脚本 API 见文末相关链接</td></tr><tr><td><strong>Input Schema</strong></td><td>JSON Schema，用于声明运行参数；运行弹窗会据此生成示例输入</td></tr></tbody></table><p>描述与 Input Schema 比代码更影响 AI 调用质量。实施时建议先把 <strong>函数边界、必填参数、返回结构</strong> 写清楚，再填执行代码；不要把密钥、外部 Token 或长期凭证硬编码到函数里。</p><h3 id="运行检查" tabindex="-1">运行检查 <a class="header-anchor" href="#运行检查" aria-label="Permalink to &quot;运行检查&quot;">​</a></h3><p>点击 <strong>运行</strong> 后，系统读取 Input Schema 并生成一份 JSON 参数。确认或调整参数后点 <strong>运行</strong>，后台调用 <code>mcp/RunTool</code> 并显示返回结果。若 Schema 没有属性，弹窗会直接运行并进入结果页。</p><h3 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to &quot;内置工具&quot;">​</a></h3>',9)),o(d,{src:"/cms/settings/settings-ai-service-built-in-tools.png",alt:"AI 函数内置工具列表",width:"1120"}),t[6]||(t[6]=r('<p>内置列表只展示 <strong>名称</strong> 与 <strong>描述</strong>。若不希望 MCP Client 调用内置工具，回到 <a href="#mcp-服务">设置</a> 打开 <strong>禁用内置 AI 工具</strong>。</p><h2 id="向量搜索-1" tabindex="-1">向量搜索 <a class="header-anchor" href="#向量搜索-1" aria-label="Permalink to &quot;向量搜索&quot;">​</a></h2><p>向量搜索 Tab 只在 <strong>设置 → 启用向量搜索</strong> 并保存后出现。列表按对象类型展示索引状态。</p><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>对象类型，如商品、页面、视图、内容等</td></tr><tr><td><strong>总数</strong></td><td>当前可索引对象数量</td></tr><tr><td><strong>未同步</strong></td><td>尚未生成向量，或对象更新时间 / 模型与索引记录不一致</td></tr><tr><td><strong>排队中</strong></td><td>已提交但未完成的索引任务</td></tr><tr><td><strong>状态</strong></td><td>显示运行中、错误、待同步或已完成</td></tr><tr><td><strong>同步</strong></td><td>对所选对象类型只处理未同步项</td></tr><tr><td><strong>重建</strong></td><td>删除所选类型已有向量后重新索引全部对象</td></tr></tbody></table><p>切换 Embedding Provider 或 Model 后，旧索引模型与当前模型不一致，通常需要对关键对象执行 <strong>重建</strong>。</p><h2 id="llms-txt-生成器" tabindex="-1">llms.txt 生成器 <a class="header-anchor" href="#llms-txt-生成器" aria-label="Permalink to &quot;llms.txt 生成器&quot;">​</a></h2><p><code>llms.txt</code> 用于给 AI 爬虫提供站点内容索引。后台读取并保存的是站点文件 <code>/llms.txt</code>。</p>',7)),o(d,{src:"/cms/settings/settings-ai-service-llms.png",alt:"llms.txt 生成器",width:"1120"}),t[7]||(t[7]=r('<table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td><strong>生成</strong></td><td>根据当前站点在线页面生成一份 <code>llms.txt</code> 草稿；每个页面链接到对应 <code>.md</code> 地址</td></tr><tr><td><strong>文本框</strong></td><td>可手动编辑最终内容</td></tr><tr><td><strong>保存</strong></td><td>将文本框内容写入根路径 <code>/llms.txt</code></td></tr></tbody></table><p>生成前建议先确认页面已上线、路由名称正确，并已按需开启 <a href="#自动-markdown-引擎">自动 Markdown 引擎</a>，这样 <code>llms.txt</code> 指向的 <code>.md</code> 链接更容易被 AI 客户端读取。</p><h2 id="自动-markdown-引擎" tabindex="-1">自动 Markdown 引擎 <a class="header-anchor" href="#自动-markdown-引擎" aria-label="Permalink to &quot;自动 Markdown 引擎&quot;">​</a></h2><p>自动 Markdown 引擎开启后，访问页面路径追加 <code>.md</code> 或 <code>index.html.md</code> 时，系统会找到原页面路由并把 HTML 渲染结果转换为 Markdown。</p>',4)),o(d,{src:"/cms/settings/settings-ai-service-markdown.png",alt:"自动 Markdown 引擎",width:"1120"}),t[8]||(t[8]=r('<h3 id="启用开关" tabindex="-1">启用开关 <a class="header-anchor" href="#启用开关" aria-label="Permalink to &quot;启用开关&quot;">​</a></h3><p>右上角 <strong>启用</strong> 开关会立即保存站点 <code>AI.MarkdownEngine.Enable</code>。关闭后，<code>.md</code> 路由不会按 Markdown 渲染。</p><h3 id="覆盖规则" tabindex="-1">覆盖规则 <a class="header-anchor" href="#覆盖规则" aria-label="Permalink to &quot;覆盖规则&quot;">​</a></h3><p>覆盖规则用于为部分路径指定适用对象或禁用规则。</p>',4)),o(d,{src:"/cms/settings/settings-ai-service-markdown-rule-dialog.png",alt:"Markdown 覆盖规则弹窗",width:"1120"}),t[9]||(t[9]=r('<table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>匹配路径</strong></td><td>需要覆盖的访问路径；建议使用真实前台路径，方便和页面路由核对</td></tr><tr><td><strong>适用对象</strong></td><td>该路径要使用的对象标识</td></tr><tr><td><strong>状态</strong></td><td>启用或禁用该覆盖规则</td></tr></tbody></table><p>新增、编辑、删除规则只改变当前表单状态，最后仍需点击底部 <strong>保存</strong> 写入站点。</p><h2 id="全局-json-ld-映射" tabindex="-1">全局 JSON-LD 映射 <a class="header-anchor" href="#全局-json-ld-映射" aria-label="Permalink to &quot;全局 JSON-LD 映射&quot;">​</a></h2><p>全局 JSON-LD 映射把 Kooboo 内容或数据库字段映射到 Schema.org 类型与属性。开启后，页面渲染时会输出 <code>application/ld+json</code> 结构化数据。</p>',4)),o(d,{src:"/cms/settings/settings-ai-service-jsonld.png",alt:"全局 JSON-LD 映射",width:"1120"}),t[10]||(t[10]=r('<h3 id="启用开关-1" tabindex="-1">启用开关 <a class="header-anchor" href="#启用开关-1" aria-label="Permalink to &quot;启用开关&quot;">​</a></h3><p>右上角 <strong>启用</strong> 开关保存站点 <code>AI.JsonLD.Enable</code>。建议先完成至少一个数据源映射，再开启到线上站点。</p><h3 id="数据源与字段映射" tabindex="-1">数据源与字段映射 <a class="header-anchor" href="#数据源与字段映射" aria-label="Permalink to &quot;数据源与字段映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><strong>Kooboo 数据源</strong></td><td>可选 <code>content</code>、<code>indexeddb</code>、<code>sqlite</code>、<code>mysql</code>、<code>sqlserver</code>、<code>mongo</code> 等当前站点可访问的数据源</td></tr><tr><td><strong>数据</strong></td><td>选择具体内容文件夹或表</td></tr><tr><td><strong>架构类型</strong></td><td>从 Schema.org 类型树中选择，如 Article、Product、Organization 等</td></tr><tr><td><strong>Kooboo 变量/字段</strong></td><td>当前数据源返回的字段列表</td></tr><tr><td><strong>Schema 属性</strong></td><td>为每个字段选择要映射的 Schema.org 属性</td></tr></tbody></table><p>内容数据源的字段来自 <a href="./../content/content-types.html">内容类型</a>；数据库数据源的字段来自对应表结构。若下拉里没有预期字段，先回到内容或数据库模块检查模型是否已经保存。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>先确认站点 <a href="./basic/general.html#站点信息">Base URL</a> 与需要的 AI Provider / Embedding 模型可用。</li><li>在 <strong>设置</strong> 中按需开启 <strong>MCP 服务</strong>、<strong>向量搜索</strong>，保存。</li><li>在 <strong>AI 函数</strong> 中创建自定义工具：写清名称、描述、标签、Input Schema，再补执行代码并用 <strong>运行</strong> 验证。</li><li>若启用向量搜索，进入 <strong>向量搜索</strong> Tab 对已有对象执行 <strong>同步</strong> 或 <strong>重建</strong>。</li><li>若希望 AI 爬虫理解站点结构，开启 <strong>自动 Markdown 引擎</strong>，再用 <strong>llms.txt 生成器</strong> 生成并保存 <code>/llms.txt</code>。</li><li>若页面需要结构化数据，先在内容类型或数据库表中整理字段，再到 <strong>全局 JSON-LD 映射</strong> 选择 Schema.org 类型并映射字段。</li></ol><h2 id="cms-与-api-模板分工" tabindex="-1">CMS 与 API / 模板分工 <a class="header-anchor" href="#cms-与-api-模板分工" aria-label="Permalink to &quot;CMS 与 API / 模板分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>看 CMS</th><th>看 API / 模板引擎</th></tr></thead><tbody><tr><td>开启 MCP 服务、复制开发连接信息</td><td>本篇 <strong>设置</strong></td><td>—</td></tr><tr><td>创建 AI 函数、填写描述与 Input Schema</td><td>本篇 <strong>AI 函数</strong></td><td><a href="./../development/code.html">开发 → 代码</a>、<a href="/kb-docs/zh/api/site/code.html">k.site Code API</a>、<a href="/kb-docs/zh/api/">KScript API</a></td></tr><tr><td>函数里读取内容、数据库或电商数据</td><td>本篇只说明函数入口</td><td><a href="/kb-docs/zh/api/content/">k.content</a>、<a href="/kb-docs/zh/api/database/">k.DB</a>、<a href="/kb-docs/zh/api/commerce/commerce.html">k.commerce</a></td></tr><tr><td>页面输出 Markdown 或 <code>llms.txt</code></td><td>本篇开关与保存路径</td><td><a href="/kb-docs/zh/templateEngine/page/">Page</a>、<a href="/kb-docs/zh/templateEngine/view/">View</a>、<a href="/kb-docs/zh/templateEngine/binding/">模板绑定</a></td></tr><tr><td>JSON-LD 字段来自内容或表</td><td>本篇选择数据源与字段映射</td><td><a href="./../content/content-types.html">内容类型</a>、<a href="./../database/">数据库</a>、<a href="/kb-docs/zh/templateEngine/k-data/">k-data</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">站点设置概述</a></td><td>站点设置菜单与子路由</td></tr><tr><td><a href="./../operations/">运维中心</a></td><td>AI 服务的同页入口</td></tr><tr><td><a href="./basic/general.html">基础设置 · 基础</a></td><td>Base URL 与站点信息</td></tr><tr><td><a href="./../development/code.html">开发 → 代码</a></td><td>KScript / TypeScript 代码资源</td></tr><tr><td><a href="./../content/content-types.html">内容类型</a></td><td>JSON-LD 内容字段来源</td></tr><tr><td><a href="./../database/">数据库</a></td><td>JSON-LD 数据库字段来源</td></tr><tr><td><a href="/kb-docs/zh/api/">KScript API</a></td><td>AI 函数执行代码可用 API</td></tr></tbody></table>',11))])}const T=n(l,[["render",h]]);export{I as __pageData,T as default};
